  (N'cmbalt', N'Casey Morgan (Baltimore City)', 'MD-BCHD'),
  (N'cmbaltco', N'Jordan Lee (Baltimore County)', 'MD-BCO'),
  (N'cmboth', N'Dana Brooks (City and County)', 'MD-BCHD'),
  (N'cityadmin', N'Erin Cole (Baltimore City administrator)', 'MD-BCHD'),
